{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Prochlorperazine, a close phenothiazine analogue with a propyl-linked basic amine side chain, has an absolute oral bioavailability of only 5.7% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Fluphenazine, another phenothiazine with a propyl-linked piperazine side chain, shows mean absolute oral bioavailability of 4.8% in healthy volunteers, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Trifluoperazine, a phenothiazine with an N-methylpiperazine propyl side chain, has small and erratic oral bioavailability (mean 6.0%, range 2–8%), consistent with low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Levomepromazine, a less similar phenothiazine with a methoxy substituent and dimethylamino side chain, shows higher oral bioavailability (33–74%), but its structural differences limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pridopidine, which shares a methylsulfonyl aryl and piperidine motif but lacks the phenothiazine core, has high oral availability in humans; this is only weakly transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues are phenothiazine antipsychotics with propyl-linked basic amine side chains; all show absolute oral bioavailability far below 20% (2.7–12.5%) in humans. The query shares the same tricyclic phenothiazine core and propyl-piperidine side chain, so low F is strongly supported. Less similar high-bioavailability compounds do not override this evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Metabolic stability and first-pass extraction of the methylsulfonyl and carboxamide piperidine substituents are not directly measured.",
    "Potential transporter or formulation effects on oral absorption are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

